import Observation
import os
import XCTest
@testable import GoLensFoundation

final class GeneratedFileOriginTests: XCTestCase {
    func testDetectsProtocGenGoOriginFromSourceCommentAndProtoStem() {
        let content = """
        // Code generated by protoc-gen-go. DO NOT EDIT.
        // versions:
        // \tprotoc-gen-go v1.34.1
        // source: user/v1/user.proto

        package userv1
        """
        let proto = "/ws/proto/user/v1/user.proto"
        let pb = "/ws/gen/user/v1/user.pb.go"
        let files: [String: String] = [
            "/ws/Makefile": "",
            proto: "syntax = \"proto3\";\n",
            "/ws/gen/user/v1/gen.go": "package userv1\n\n//go:generate protoc --go_out=. user/v1/user.proto\n"
        ]

        let origin = GeneratedFileOrigin.resolve(
            content: content,
            goFilePath: pb,
            workspaceRoot: "/ws",
            readFile: { files[$0] },
            listDirectory: { dir in
                if dir == "/ws/gen/user/v1" { return ["gen.go", "user.pb.go"] }
                return []
            },
            fileExists: { files[$0] != nil }
        )

        XCTAssertEqual(origin?.generator, "protoc-gen-go")
        XCTAssertEqual(origin?.sourcePath, proto)
        XCTAssertEqual(origin?.sourceDisplayName, "proto/user/v1/user.proto")
        XCTAssertEqual(origin?.generateDirective?.command, "protoc --go_out=. user/v1/user.proto")
        XCTAssertEqual(origin?.generateDirective?.line, 3)
    }

    func testDetectsMockgenAndStringerWithSourceAndGenerateDirectives() {
        let mockContent = """
        // Code generated by MockGen. DO NOT EDIT.
        // Source: store.go (interfaces: Reader)

        package store
        """
        let files: [String: String] = [
            "/ws/pkg/store.go": "package store\n\n//go:generate mockgen -source=store.go -destination=mock_store.go -package=store\n\ntype Reader interface {\n\tGet() string\n}\n",
            "/ws/pkg/status.go": "package store\n\n//go:generate stringer -type=Status\n\ntype Status int\n"
        ]

        let mockOrigin = GeneratedFileOrigin.resolve(
            content: mockContent,
            goFilePath: "/ws/pkg/mock_store.go",
            workspaceRoot: "/ws",
            readFile: { files[$0] },
            listDirectory: { $0 == "/ws/pkg" ? ["mock_store.go", "status.go", "store.go"] : [] },
            fileExists: { files[$0] != nil }
        )
        XCTAssertEqual(mockOrigin?.generator, "mockgen")
        XCTAssertEqual(mockOrigin?.sourcePath, "/ws/pkg/store.go")
        XCTAssertEqual(mockOrigin?.generateDirective?.filePath, "/ws/pkg/store.go")

        let stringerContent = """
        // Code generated by "stringer -type=Status"; DO NOT EDIT.

        package store
        """
        let stringerOrigin = GeneratedFileOrigin.resolve(
            content: stringerContent,
            goFilePath: "/ws/pkg/status_string.go",
            workspaceRoot: "/ws",
            readFile: { files[$0] },
            listDirectory: { $0 == "/ws/pkg" ? ["status.go", "status_string.go", "store.go"] : [] },
            fileExists: { files[$0] != nil }
        )
        XCTAssertEqual(stringerOrigin?.generator, "stringer")
        XCTAssertEqual(stringerOrigin?.sourcePath, "/ws/pkg/status.go")
        XCTAssertEqual(stringerOrigin?.defaultLine, 5)
        XCTAssertEqual(stringerOrigin?.generateDirective?.command, "stringer -type=Status")
    }

    func testDetectsOapiCodegenEntWireAndSqlcOrigins() {
        let files: [String: String] = [
            "/ws/api/openapi.yaml": "openapi: 3.0.3\n",
            "/ws/api/gen.go": "package api\n\n//go:generate go run github.com/oapi-codegen/oapi-codegen/v2/cmd/oapi-codegen -config cfg.yaml openapi.yaml\n",
            "/ws/ent/schema/user.go": "package schema\n",
            "/ws/ent/generate.go": "package ent\n\n//go:generate go run -mod=mod entgo.io/ent/cmd/ent generate ./schema\n",
            "/ws/di/wire.go": "//go:build wireinject\npackage di\n\nfunc Init() {}\n",
            "/ws/db/queries.sql": "-- name: GetUser :one\nSELECT * FROM users;\n",
            "/ws/db/sqlc.yaml": "version: \"2\"\n"
        ]

        let oapi = GeneratedFileOrigin.resolve(
            content: "// Code generated by github.com/oapi-codegen/oapi-codegen version v2.3.0 DO NOT EDIT.\npackage api\n",
            goFilePath: "/ws/api/server.gen.go",
            workspaceRoot: "/ws",
            readFile: { files[$0] },
            listDirectory: { $0 == "/ws/api" ? ["gen.go", "server.gen.go"] : [] },
            fileExists: { files[$0] != nil }
        )
        XCTAssertEqual(oapi?.generator, "oapi-codegen")
        XCTAssertEqual(oapi?.sourcePath, "/ws/api/openapi.yaml")

        let ent = GeneratedFileOrigin.resolve(
            content: "// Code generated by ent, DO NOT EDIT.\npackage ent\n",
            goFilePath: "/ws/ent/user.go",
            workspaceRoot: "/ws",
            readFile: { files[$0] },
            listDirectory: { $0 == "/ws/ent" ? ["generate.go", "user.go"] : [] },
            fileExists: { files[$0] != nil }
        )
        XCTAssertEqual(ent?.generator, "ent")
        XCTAssertEqual(ent?.sourcePath, "/ws/ent/schema/user.go")

        let wire = GeneratedFileOrigin.resolve(
            content: "// Code generated by Wire. DO NOT EDIT.\npackage di\n",
            goFilePath: "/ws/di/wire_gen.go",
            workspaceRoot: "/ws",
            readFile: { files[$0] },
            listDirectory: { $0 == "/ws/di" ? ["wire.go", "wire_gen.go"] : [] },
            fileExists: { files[$0] != nil }
        )
        XCTAssertEqual(wire?.generator, "wire")
        XCTAssertEqual(wire?.sourcePath, "/ws/di/wire.go")

        let sqlc = GeneratedFileOrigin.resolve(
            content: "// Code generated by sqlc. DO NOT EDIT.\n// source: queries.sql\npackage db\n",
            goFilePath: "/ws/db/queries.sql.go",
            workspaceRoot: "/ws",
            readFile: { files[$0] },
            listDirectory: { $0 == "/ws/db" ? ["queries.sql.go"] : [] },
            fileExists: { files[$0] != nil }
        )
        XCTAssertEqual(sqlc?.generator, "sqlc")
        XCTAssertEqual(sqlc?.sourcePath, "/ws/db/queries.sql")
    }

    func testMapsLineDirectivesToExactSourceLineAndIgnoresNormalGoFiles() {
        let content = """
        // Code generated by templ - DO NOT EDIT.

        package ui

        func Page() {
        //line components/page.templ:42
        \t_ = "line 42"
        \t_ = "line 43"
        //line components/header.templ:9:3
        \t_ = "header line 9"
        }
        """
        let exists: (String) -> Bool = {
            $0 == "/ws/components/page.templ" || $0 == "/ws/components/header.templ"
        }

        let first = GeneratedFileOrigin.mappedOriginLocation(
            in: content,
            forGeneratedLine: 8,
            goFilePath: "/ws/components/page_templ.go",
            workspaceRoot: "/ws",
            fileExists: exists
        )
        XCTAssertEqual(first?.path, "/ws/components/page.templ")
        XCTAssertEqual(first?.line, 43)

        let second = GeneratedFileOrigin.mappedOriginLocation(
            in: content,
            forGeneratedLine: 10,
            goFilePath: "/ws/components/page_templ.go",
            workspaceRoot: "/ws",
            fileExists: exists
        )
        XCTAssertEqual(second?.path, "/ws/components/header.templ")
        XCTAssertEqual(second?.line, 9)

        XCTAssertNil(GeneratedFileOrigin.resolve(
            content: "package main\n\nfunc main() {}\n",
            goFilePath: "/ws/main.go",
            workspaceRoot: "/ws"
        ))
    }

    func testMapsRelativeLineDirectiveWithoutColumnUsingOneBasedIssueLine() {
        let content = [
            "// Code generated by protoc-gen-go. DO NOT EDIT.",
            "package gen",
            "",
            "func _() {}",
            "func _() {}",
            "func _() {}",
            "func _() {}",
            "func _() {}",
            "func _() {}",
            "//line ../api/greet.proto:4",
            "var _ = UndefinedSymbol",
            "var _ = NextProtoLine"
        ].joined(separator: "\n")

        let exists: (String) -> Bool = { $0 == "/ws/api/greet.proto" }

        let line11 = GeneratedFileOrigin.mappedOriginLocation(
            in: content,
            forGeneratedLine: 11,
            goFilePath: "/ws/gen/greet.pb.go",
            workspaceRoot: "/ws",
            fileExists: exists
        )
        XCTAssertEqual(line11?.path, "/ws/api/greet.proto")
        XCTAssertEqual(line11?.line, 4)

        let line12 = GeneratedFileOrigin.mappedOriginLocation(
            in: content,
            forGeneratedLine: 12,
            goFilePath: "/ws/gen/greet.pb.go",
            workspaceRoot: "/ws",
            fileExists: exists
        )
        XCTAssertEqual(line12?.path, "/ws/api/greet.proto")
        XCTAssertEqual(line12?.line, 5)
    }

    func testCacheAvoidsObservableInvalidationWhenOriginIsUnchanged() {
        let cache = GeneratedFileOriginCache()
        let mainPath = "/ws/main.go"
        let genPath = "/ws/gen/greet.pb.go"
        let protoPath = "/ws/api/greet.proto"
        let nonGeneratedText = "package main\n\nfunc main() {}\n"
        let generatedTextV1 = [
            "// Code generated by protoc-gen-go. DO NOT EDIT.",
            "// source: api/greet.proto",
            "",
            "package gen",
            "var A = 1"
        ].joined(separator: "\n")
        let generatedTextV2 = generatedTextV1 + "\nvar B = 2\n"
        let exists: (String) -> Bool = { $0 == protoPath }
        let noFiles: (String) -> String? = { _ in nil }
        let emptyDir: (String) -> [String] = { _ in [] }

        cache.refreshImmediately(
            for: mainPath,
            text: nonGeneratedText,
            version: 1,
            workspaceRoot: "/ws",
            readFile: noFiles,
            listDirectory: emptyDir,
            fileExists: exists
        )
        XCTAssertNil(cache.origin(for: mainPath))

        for version in 2...5 {
            let changes = measureOriginInvalidations(on: cache, path: mainPath) {
                cache.refreshImmediately(
                    for: mainPath,
                    text: nonGeneratedText + "\n// edit \(version)\n",
                    version: version,
                    workspaceRoot: "/ws",
                    readFile: noFiles,
                    listDirectory: emptyDir,
                    fileExists: exists
                )
            }
            XCTAssertEqual(changes, 0)
        }

        let absentRemovalChanges = measureOriginInvalidations(on: cache, path: mainPath) {
            XCTAssertFalse(cache.remove(for: "/ws/not_cached.go"))
        }
        XCTAssertEqual(absentRemovalChanges, 0)

        cache.refreshImmediately(
            for: genPath,
            text: nonGeneratedText,
            version: 1,
            workspaceRoot: "/ws",
            readFile: noFiles,
            listDirectory: emptyDir,
            fileExists: exists
        )

        let becameGeneratedChanges = measureOriginInvalidations(on: cache, path: genPath) {
            cache.refreshImmediately(
                for: genPath,
                text: generatedTextV1,
                version: 2,
                workspaceRoot: "/ws",
                readFile: noFiles,
                listDirectory: emptyDir,
                fileExists: exists
            )
        }
        XCTAssertEqual(becameGeneratedChanges, 1)
        XCTAssertEqual(cache.origin(for: genPath)?.generator, "protoc-gen-go")
        XCTAssertEqual(cache.origin(for: genPath)?.sourcePath, protoPath)

        let unchangedGeneratedChanges = measureOriginInvalidations(on: cache, path: genPath) {
            cache.refreshImmediately(
                for: genPath,
                text: generatedTextV2,
                version: 3,
                workspaceRoot: "/ws",
                readFile: noFiles,
                listDirectory: emptyDir,
                fileExists: exists
            )
        }
        XCTAssertEqual(unchangedGeneratedChanges, 0)

        let becameNormalChanges = measureOriginInvalidations(on: cache, path: genPath) {
            cache.refreshImmediately(
                for: genPath,
                text: nonGeneratedText,
                version: 4,
                workspaceRoot: "/ws",
                readFile: noFiles,
                listDirectory: emptyDir,
                fileExists: exists
            )
        }
        XCTAssertEqual(becameNormalChanges, 1)
        XCTAssertNil(cache.origin(for: genPath))

        let firstClearChanges = measureOriginInvalidations(on: cache, path: genPath) {
            XCTAssertTrue(cache.clear())
        }
        XCTAssertEqual(firstClearChanges, 1)

        let secondClearChanges = measureOriginInvalidations(on: cache, path: genPath) {
            XCTAssertFalse(cache.clear())
        }
        XCTAssertEqual(secondClearChanges, 0)
    }

    private func measureOriginInvalidations(
        on cache: GeneratedFileOriginCache,
        path: String,
        during operation: () -> Void
    ) -> Int {
        let invalidations = OSAllocatedUnfairLock(initialState: 0)
        withObservationTracking {
            _ = cache.origin(for: path)
        } onChange: {
            invalidations.withLock { $0 += 1 }
        }
        operation()
        return invalidations.withLock { $0 }
    }
}
